contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt);
        require(withdrawAmt > depositAmt);
        c.deposit{value: depositAmt}();
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawAmt) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 depositAmt) public payable {
        require(depositAmt > 0);
        require(address(this).balance >= depositAmt);
        c.deposit{value: depositAmt}();
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.refund() { reverted = false; }
        catch { reverted = true; }
        uint256 balAfter = address(c).balance;
        assert(!reverted && balBefore >= depositAmt && balAfter == balBefore - depositAmt);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        bool refundReverted;
        try c.refund() { refundReverted = false; } catch { refundReverted = true; }
        require(!refundReverted);
        bool withdrawReverted;
        try c.withdraw(amount) { withdrawReverted = false; } catch { withdrawReverted = true; }
        assert(withdrawReverted);
    }
    receive() external payable {}
}
